import React, { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState } from "react";
import TimelineBar from "./TimelineBar";

function inAnyRange(t, ranges) {
  for (const r of ranges || []) {
    const a = Number(r.start_s || 0);
    const b = Number(r.end_s || 0);
    if (t >= a && t <= b) return true;
  }
  return false;
}

const VideoPlayer = forwardRef(function VideoPlayer({ src, ranges, onDuration }, ref) {
  const videoRef = useRef(null);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);

  const isInTampered = useMemo(() => inAnyRange(currentTime, ranges), [currentTime, ranges]);

  useEffect(() => {
    const v = videoRef.current;
    if (!v) return;

    const onTime = () => setCurrentTime(v.currentTime || 0);
    const onMeta = () => {
      const d = v.duration || 0;
      setDuration(d);
      onDuration?.(d);
    };
    const onPlay = () => setIsPlaying(true);
    const onPause = () => setIsPlaying(false);
    v.addEventListener("timeupdate", onTime);
    v.addEventListener("loadedmetadata", onMeta);
    v.addEventListener("play", onPlay);
    v.addEventListener("pause", onPause);
    return () => {
      v.removeEventListener("timeupdate", onTime);
      v.removeEventListener("loadedmetadata", onMeta);
      v.removeEventListener("play", onPlay);
      v.removeEventListener("pause", onPause);
    };
  }, [onDuration]);

  const seek = (t) => {
    const v = videoRef.current;
    if (!v) return;
    v.currentTime = Math.max(0, Math.min(duration || v.duration || 0, t));
    v.play?.();
  };

  const togglePlay = async () => {
    const v = videoRef.current;
    if (!v) return;
    if (v.paused) {
      await v.play?.();
    } else {
      v.pause?.();
    }
  };

  useImperativeHandle(ref, () => ({ seek }), [duration]);

  return (
    <div>
      <div style={styles.videoWrap(isInTampered)}>
        <video ref={videoRef} src={src} controls={false} style={styles.video} />
      </div>
      <div style={styles.controlsRow}>
        <button onClick={togglePlay} style={styles.playBtn}>
          {isPlaying ? "Pause" : "Play"}
        </button>
        <div style={styles.timeText}>
          {formatTime(currentTime)} / {formatTime(duration)}
        </div>
      </div>
      <div style={{ marginTop: 10 }}>
        <TimelineBar duration={duration} currentTime={currentTime} ranges={ranges} onSeek={seek} />
      </div>
    </div>
  );
});

export default VideoPlayer;

function formatTime(seconds) {
  const s = Math.max(0, Number(seconds) || 0);
  const mm = Math.floor(s / 60);
  const ss = Math.floor(s % 60);
  return `${String(mm).padStart(2, "0")}:${String(ss).padStart(2, "0")}`;
}

const styles = {
  videoWrap: (isTamperedNow) => ({
    borderRadius: 12,
    overflow: "hidden",
    border: `3px solid ${isTamperedNow ? "#ef4444" : "#e5e7eb"}`,
    boxShadow: "0 2px 10px rgba(0,0,0,0.04)",
  }),
  video: {
    width: "100%",
    display: "block",
    background: "#000",
  },
  controlsRow: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    gap: 12,
    marginTop: 10,
  },
  playBtn: {
    padding: "10px 14px",
    borderRadius: 10,
    border: "none",
    background: "#111827",
    color: "white",
    cursor: "pointer",
    fontWeight: 700,
    minWidth: 92,
  },
  timeText: {
    color: "#6b7280",
    fontSize: 13,
    fontVariantNumeric: "tabular-nums",
  },
};
